import XCTest
@testable import vevc

final class CDF97Tests: XCTestCase {
    // スカラー参照実装 (SIMD ビット一致検証用オラクル)
    enum CDF97Ref {
        static let cA: Int32 = -25987
        static let cB: Int32 = -868
        static let cG: Int32 = 14466
        static let cD: Int32 = 7266
        static let cIK: Int32 = 13318
        static let cK: Int32 = 20155
        
        static func mulShift(_ c: Int32, _ v: Int32) -> Int32 {
            return (v &* c &+ 8192) &>> 14
        }

        static func forward(_ x: inout [Int16]) {
            let half = x.count / 2
            var L = (0..<half).map { Int32(x[2*$0]) }
            var H = (0..<half).map { Int32(x[2*$0+1]) }
            func cl(_ i: Int) -> Int32 { L[min(max(i, 0), half-1)] }
            func ch(_ i: Int) -> Int32 { H[min(max(i, 0), half-1)] }
            for i in 0..<half { H[i] += mulShift(cA, cl(i) + cl(i+1)) }
            for i in 0..<half { L[i] += mulShift(cB, ch(i-1) + H[i]) }
            for i in 0..<half { H[i] += mulShift(cG, cl(i) + cl(i+1)) }
            for i in 0..<half { L[i] += mulShift(cD, ch(i-1) + H[i]) }
            for i in 0..<half {
                x[i] = Int16(truncatingIfNeeded: L[i])
                x[half+i] = Int16(truncatingIfNeeded: H[i])
            }
        }

        static func inverse(_ x: inout [Int16]) {
            let half = x.count / 2
            var L = (0..<half).map { Int32(x[$0]) }
            var H = (0..<half).map { Int32(x[half+$0]) }
            func cl(_ i: Int) -> Int32 { L[min(max(i, 0), half-1)] }
            func ch(_ i: Int) -> Int32 { H[min(max(i, 0), half-1)] }
            for i in 0..<half { L[i] -= mulShift(cD, ch(i-1) + H[i]) }
            for i in 0..<half { H[i] -= mulShift(cG, cl(i) + cl(i+1)) }
            for i in 0..<half { L[i] -= mulShift(cB, ch(i-1) + H[i]) }
            for i in 0..<half { H[i] -= mulShift(cA, cl(i) + cl(i+1)) }
            for i in 0..<half {
                x[2*i] = Int16(truncatingIfNeeded: L[i])
                x[2*i+1] = Int16(truncatingIfNeeded: H[i])
            }
        }
    }

